import type { Option, Paper, Paragraph, Passage } from '@/types/paper';

/**
 * 2024 年 12 月大学英语六级真题（第 1–3 套）站内作答数据。
 * 检索日期：2026-11-19。
 * 来源与核验：
 * - 题面 / 选项 / 答案 / 选词填空词库 / 长篇阅读段落 / 写作范文 / 翻译参考译文：
 *   过级鸭 guojiya.cn/exam/cet6_2024_12_N/answers（整卷结构化页面，2026-11-19 逐套抓取）。
 * - 听力原文：词通英语 wordcram.com.cn/tests/cet6/listening/2024-12-N（精听页逐句英文 + 中文对照）。
 * - 答案以过级鸭所载答案表为准，选词填空 26–35、长篇阅读 36–45 的答案取自其「答案与解析」区。
 * - 听力部分给出原文，由站内合成朗读（非考试原音）；官方从不发布历年真题与听力音频。
 * - 写作范文与翻译参考译文均为机构参考版本，非唯一正确写法。
 */

/** 长篇阅读选项：由各段落生成（key=段落标记，text=段落首句，超过 60 字符截断） */
function matchOptions(paras: Paragraph[]): Option[] {
  return paras
    .filter((p): p is Paragraph & { marker: string } => Boolean(p.marker))
    .map((p) => {
      const dot = p.text.indexOf('. ');
      const first = dot > 0 ? p.text.slice(0, dot + 1) : p.text;
      const text = first.length > 60 ? `${first.slice(0, 60).replace(/[\s,;:]+$/, '')}…` : first;
      return { key: p.marker, text: `${p.marker}) ${text}` };
    });
}

/** cet6-2024-12-s1 长篇阅读段落 */
const mp_cet6_2024_12_s1: Passage = {
  id: 'cet6-2024-12-s1-mp',
  title: '长篇阅读（信息匹配）',
  paragraphs: [
    { id: 'cet6-2024-12-s1-mp-A', marker: 'A', text: `On a small fruit farm near the Straits of Malacca, Lim Kok Ann is down to just one tree growing kedondong, a crunchy, sour berry that Malaysians mostly use in pickles (腌菜) and salads. "It's not very well-known," says the 45-year-old, who is instead focusing on longan (龙眼) berries and pineapples, which have bigger markets. "We have to grow what is profitable," he says.` },
    { id: 'cet6-2024-12-s1-mp-B', marker: 'B', text: `But less than an hour away in the Malaysian countryside, inside three giant, silver domes, scientists are trying to change the future of food. They're pushing the boundaries of what humans eat by growing and processing so-called 'alternative' crops—such as kedondong. At the headquarters of global research centre Crops For the Future (CFF) this particular under-used fruit has been turned into a sugar-free juice, high in vitamin C and getting top marks in sensory evaluations. "Anything you see here is a forgotten crop," says Sayed Azam-Ali of the abundant plants weaving through the gardens of CFF outside Malaysia's capital Kuala Lumpur.` },
    { id: 'cet6-2024-12-s1-mp-C', marker: 'C', text: `Prof Azam-Ali explains that just four crops—wheat, maize, rice and soybean—provide two-thirds of the world's food supply. "We're dependent on these four," he says. "But actually there's 7,000 crops we've been farming for thousands of years. We ignore all of those." Researchers are trying to unlock the potential of these ignored crops—plants they describe as forgotten, under-used or 'alternative' as they are displaced by increasingly uniform diets fuelled by processed ingredients from the major crops.` },
    { id: 'cet6-2024-12-s1-mp-D', marker: 'D', text: `It's a timely quest. The food sector is already responsible for nearly a third of global greenhouse gas emissions. By 2050 it estimates the world must produce 50% more food to feed the projected global population of 10 billion. Meeting this demand without contributing to climate change calls for urgent solutions.` },
    { id: 'cet6-2024-12-s1-mp-E', marker: 'E', text: `Forgotten crops hold key answers. By investing in neglected local plants, countries can reduce their reliance on imported crops and their carbon-heavy supply chains. Bringing back the variety of crops humans once ate also boosts food security at a time warming climates threaten existing crops. On top of that forgotten crops are among the most climate-resilient (具有气候韧性的) and nutritious, argues Azam-Ali. His summary is plain: "Dietary diversification is critical to the future of humanity."` },
    { id: 'cet6-2024-12-s1-mp-F', marker: 'F', text: `Food security experts agree. "There is no food insecurity in the world, there is food ignorance," says Cecilia Tortajada, a senior research fellow at the Institute of Water Policy at the National University of Singapore. "Whenever we have native crops we tend to disregard them as if they were not valuable but they are," she adds.` },
    { id: 'cet6-2024-12-s1-mp-G', marker: 'G', text: `Azam-Ali knows that scepticism firsthand. He came across alternative crops in the 1980s through the work of women farmers he met in Niger. The then-PhD student remembers marvelling at the crops they grew in their backyards, without the benefits of technology, to feed their families when the big crops failed. He saw a tremendous opportunity to build alternative food systems. But "the resistance was enormous," he recalls.` },
    { id: 'cet6-2024-12-s1-mp-H', marker: 'H', text: `Undeterred, he ploughed on. Project after project helped prove these crops were viable in different environments as alternatives to the staple ones. But the question of whether these crops would be marketable remained. "That's the critical thing," he says. In one of the centre's domes, food technologist Tan Xinlin uses powdered moringa (辣木) leaves in place of some wheat flour to bake a cake lower in gluten (谷胶) and higher in nutrients. Tan's job is to create recipes with these still-unfamiliar ingredients that will appeal to both local and international tastes. In recent years she has used some of the forgotten crops grown at CFF, such as moringa and bambara groundnut, to make everything from instant soup to Indian snacks. "I try to modernise forgotten crops instead of using old recipes," says Tan, who is also a trained chef. It's a strategy to appeal to the world's growing middle classes who are increasingly turning to the fast and processed food industries. It's also a way to help counter perceptions of local crops as "old or poor people's food" or as inferior "women's crops", adds Tan.` },
    { id: 'cet6-2024-12-s1-mp-I', marker: 'I', text: `The roots of these connotations about local foods can run deep. The bambara groundnut, a protein-rich native crop of sub-Saharan Africa that is also grown in parts of southeast Asia, can trace its marginalisation to colonial rule. "African women who grew bambara groundnut were actually punished for growing it," says Azam-Ali. "Colonial powers said you can't grow that because there's no oil. We can't get a market for it." But today the bambara murukku is one of CFF's best-reviewed foods and they are aiming to get it into grocery stores, pointing to the success of crops like quinoa to potential investors. Some 30 years ago, quinoa was virtually unheard of outside its native mountains in Bolivia and Peru. Today the nutritious grain is found on the menus of lavish restaurants across the world.` },
    { id: 'cet6-2024-12-s1-mp-J', marker: 'J', text: `Measuring crops by nutrition instead of yield is at the heart of the forgotten foods enterprise. Ever since the "green revolution" of the 1960s, high-yielding crops have dominated modern agriculture. That was in part a crucial response to devastating famines at a time when the world needed to increase its food supply. Today "nutrition is becoming a time bomb", says Azam-Ali, as growing carbon dioxide levels strip crops of their minerals. Instead of bio-fortifying major crops we should be investing in those forgotten crops that are already more nutritious, he asserts.` },
    { id: 'cet6-2024-12-s1-mp-K', marker: 'K', text: `In the bowels of CFF's third dome, lab manager Gomathy Sethuraman opens a window into the centre's "crown jewels", revealing vines of winged beans growing under a bright yellow light. It's one of multiple chambers where scientists are studying the impact of higher temperatures and carbon dioxide levels on the nutritional make-up of alternative crops. This research is "the game changer", says Azam-Ali, ensuring that 'future crops' are also the healthiest ones in warmer climates.` },
    { id: 'cet6-2024-12-s1-mp-L', marker: 'L', text: `There is a growing global momentum around forgotten foods, says Danielle Nierenberg, president of Food Tank, a US-based think tank. Other than CFF, which bills itself as the world's first research centre dedicated solely to under-utilised crops, there are other key groups championing agricultural diversity including Crop Trust, Slow Food, Icrisat and Bioversity International. Add to that more middle-income consumers searching for nutritious foods and others eager to try the unprocessed foods their grandparents once ate, she says.` },
    { id: 'cet6-2024-12-s1-mp-M', marker: 'M', text: `But the rising interest in forgotten foods in some quarters is overtaken by the global spread of Western-style diets heavy in sugar, fat and processed foods in others.` },
    { id: 'cet6-2024-12-s1-mp-N', marker: 'N', text: `A key obstacle to promoting fading local crops in Malaysia, for example, is "the obsession with imported products", says Jenifer Kuala, co-founder of a restaurant that champions locally-sourced food in an affluent suburb of Kuala Lumpur. Customers at Sitka, regarded as a pioneer in the country's small farm-to-table dining scene, still seek foreign ingredients as a "status symbol", she says.` },
    { id: 'cet6-2024-12-s1-mp-O', marker: 'O', text: `The argument for forgotten foods feels intuitive. Some analysts say it is in fact inevitable. "Climate change is going to mean almost certainly tastes are going to be forced to change," says Tim Lang, professor of food policy at City University of London. We "have to get used to eating other crops" as yields of staple crops fall, he says.` },
  ],
};
/** cet6-2024-12-s2 长篇阅读段落 */
const mp_cet6_2024_12_s2: Passage = {
  id: 'cet6-2024-12-s2-mp',
  title: '长篇阅读（信息匹配）',
  paragraphs: [
    { id: 'cet6-2024-12-s2-mp-A', marker: 'A', text: `Blue moons, rose moons, supermoons. For some reason all the websites seem to think you really want to know all about these moons. "Catch This Weekend's AMAZING SUPERMOON," one headline will announce. "The Supermoon Isn't Actually A Big Deal And You're All Ruining Astronomy," another will complain.` },
    { id: 'cet6-2024-12-s2-mp-B', marker: 'B', text: `The latest example is the super blood wolf moon eclipse which sounds like the name of an emotional song I would have performed a modern dance routine to in 9th grade, but is, in fact, an astronomical event set to occur on January 20. As we'll explain below, there is nothing truly mysterious or otherwise special about this moon, and it will not look like a bloody wolf head in the sky or anything wild like that. We get these super lunar events by smashing together all the qualifiers we've historically used to keep track of full moons throughout the year, and in the age of the internet we can get a little too enthusiastic.` },
    { id: 'cet6-2024-12-s2-mp-C', marker: 'C', text: `Consider this your go-to resource for all moon-gazing news. Here's what you need to know about the latest lunar event.` },
    { id: 'cet6-2024-12-s2-mp-D', marker: 'D', text: `Look, it's okay if you don't know. There are probably loads of folks who walk around pretending they totally know why that thing in the sky seems to get bigger and smaller at regular intervals but who totally do not.` },
    { id: 'cet6-2024-12-s2-mp-E', marker: 'E', text: `The moon orbits Earth, and it's tidally locked—that means it always shows us the same face, instead of spinning around like our planet does. That's why you can always see the man on the moon (or the moon rabbit, depending on your cultural preferences) even as it spins around us. But while the moon is big and bright in the sky when it's full, that's only because it's reflecting light from the sun. But the moon is always moving, so it's getting hit with sunlight at different angles. It's invisible to us during the new moon, because our satellite is parked right between us and the sun; the so-called dark side of the moon is lit up like Las Vegas, but the side we can see is in shadow. A full moon happens when the earth is right between the sun and the moon, so sunlight hits the part we can see. And all the other phases are just the transition from one of those extremes to the other.` },
    { id: 'cet6-2024-12-s2-mp-F', marker: 'F', text: `The moon isn't always exactly the same distance from Earth, because its orbit isn't perfectly circular. We call the closest point perigee (近地点), and the most distant point is apogee (远地点). 2018's closest perigee and most distant apogee both happened in January, and the difference was about 30,000 miles.` },
    { id: 'cet6-2024-12-s2-mp-G', marker: 'G', text: `The reason you care about this ordinary change in distance is that it turns a moon super. When a full moon happens close to perigee, it's going to look a bit bigger. Honestly, the difference is not that profound, but if you're in a position to photograph the supermoon next to something that shows the slight increase in scale, it can look pretty cool. January's super blood wolf moon eclipse is super because the date lines up with the closest the moon will get to us during January, but the moon won't actually be at its closest for the year until February's supermoon, which you can expect plenty of undue excitement over.` },
    { id: 'cet6-2024-12-s2-mp-H', marker: 'H', text: `Blood moons only occur during total lunar eclipses (which can happen a few times a year in any given location). When the moon slips through our shadow, we give it a reddish coloring. The moon can also look orange whenever it's rising or setting, or if it hangs low in the horizon all night—the light bouncing off of it has to travel through a thicker atmosphere there, which scatters more blue light away. But you'll probably only see that deep, sinister red during an eclipse.` },
    { id: 'cet6-2024-12-s2-mp-I', marker: 'I', text: `A lot of headlines about moons are just ridiculous (you do not need to be particularly excited about a blue moon, it just looks like a regular full moon), but you should definitely roll out of bed to look at a blood moon if one is going to be visible in your region, even though they're just lunar eclipses and not evidence of bloody battles between the sky gods.` },
    { id: 'cet6-2024-12-s2-mp-J', marker: 'J', text: `In March of 2018, we had our second "blue moon" of the year, to much acclaim. And while that's not necessarily special in an oh-gosh-get-out-and-look-at-it way, it's certainly special: a blue moon is a nickname for when two full moons fall in the same calendar month, and we hadn't previously had two in one year since 1999. We won't have it happen again until 2037. Astronomer David Chapman explained that this is merely a peculiarity of our calendar; once we stopped doing things based on the moon and started trying to follow the sun and the seasons, we stopped having one reliable full moon per month. The moon cycle is 29.53 days long on average, so in most months we still end up with a single new moon and a single full one. But every once in a while, one month steals a full moon from another. In 2018 (and in 1999, and again in 2037) both January and March stacked full moons on the first and last nights of the month, leaving February in the dark.` },
    { id: 'cet6-2024-12-s2-mp-K', marker: 'K', text: `Getting two blue moons a year is rare, but we have individual blue moons every few years. Also, fun fact: not actually blue. A moon can indeed take on a moody blue color, but this only happens when particles of just the right size disperse through the sky—and it has nothing to do with the moon's status as "blue." Big clouds of ash from volcanic eruptions or fires can do the trick, but it doesn't happen often, and the stars would certainly have to align for two such rare instances to occur at once.` },
    { id: 'cet6-2024-12-s2-mp-L', marker: 'L', text: `You may have heard that the super special second blue moon of 2018 was also a Paschal moon. This is true! That just means it was the first full moon of spring, which is often used to determine the date of Easter Sunday. All of this is just calendar nonsense and we refuse to go into it further.` },
    { id: 'cet6-2024-12-s2-mp-M', marker: 'M', text: `Sometimes you'll see a headline that promises a moon with so many qualifiers it makes your head spin. A super blue blood worm moon, perhaps? Or a super blood wolf moon? Lots of websites will tell you that "wolf moon" is the traditional name of the first full moon of the year in "Native American" cultures, which is kind of a weird thing to claim given that there are 573 registered Tribal Nations in the U.S. alone today, not to mention historically. The idea that hungry, howling wolves were such a universal constant in January that all of North America with its different cultures, geographies, and languages spontaneously came up with the same nickname is illogical.` },
    { id: 'cet6-2024-12-s2-mp-N', marker: 'N', text: `Many cultures have traditional names for the full moon in a given month or season, so there's quite a list to draw from if you're trying to really juice up a story on a slightly-bigger-than-average view of the moon. But these are all based on human calendars and activities and folklore; you will not go outside and see a pink moon in April, though I wish it were so.` },
  ],
};
/** cet6-2024-12-s3 长篇阅读段落 */
const mp_cet6_2024_12_s3: Passage = {
  id: 'cet6-2024-12-s3-mp',
  title: '长篇阅读（信息匹配）',
  paragraphs: [
    { id: 'cet6-2024-12-s3-mp-A', marker: 'A', text: `Trade is one of the policy areas where the hostility that exists between populists (民粹主义者) and classical liberals is most visible. Free-traders point to the undeniable good that tariff-free trade has done for consumers across the world and to the observable alleviation of poverty in corners of the world where previously closed markets have been opened up. Protectionists point to the domestic producers who've paid the price for this globalized economy in the form of lost livelihoods and hollowed-out communities.` },
    { id: 'cet6-2024-12-s3-mp-B', marker: 'B', text: `The ongoing conservative civil war often degenerates into content-free tribal warfare, but trade is a rare exception. There are substantial, thought-out policy proposals on both sides of the argument.` },
    { id: 'cet6-2024-12-s3-mp-C', marker: 'C', text: `Consequently, trade as a topic of discussion provides an opportunity for liberals and populists to have a real meeting of minds. Fruitful debates might actually take place in this area, as opposed to the familiar ritual we've become accustomed to of condemnation met with counter-condemnation.` },
    { id: 'cet6-2024-12-s3-mp-D', marker: 'D', text: `Strange as it might sound, the problem with trade in the modern world isn't a matter of dollars and cents. It's a matter of false consciousness. This observation is bound to set Marxist alarm bells ringing in the minds of some readers, but it was first made by Alexis de Tocqueville in 1840.` },
    { id: 'cet6-2024-12-s3-mp-E', marker: 'E', text: `Tracking the economic development of mankind from primitive to modern societies, Tocqueville observed a paradox unfolding over the centuries as economic realities and human experience of those realities strayed further and further from each other. In primitive societies, he notes, the division of labor was as yet undeveloped for the most part, requiring each person, family, or tribe to be relatively independent when it came to meeting their own basic material needs. Men built their own dwellings, farmed their own land, tended to their own livestock. This is not to deny that basic forms of trade took place, but, for the most part, our primitive ancestors lived fairly self-reliant, if crushingly poor, lives.` },
    { id: 'cet6-2024-12-s3-mp-F', marker: 'F', text: `However, the exclusively local and face-to-face nature of economic and political organization in the ancient and prehistoric worlds constantly impressed upon these primitive peoples the uncontrollable reality of others and their needs. As Tocqueville notes, "as soon as a man begins to deal with common affairs in public, he begins to perceive that he is not so independent of his fellow men as he had first imagined, and that in order to obtain their support he must often lend them his cooperation."` },
    { id: 'cet6-2024-12-s3-mp-G', marker: 'G', text: `At the advent of the modern world, the division of labor spread further and further throughout society. Each person became more and more dependent on others for their basic needs. And yet, robbed of the engagement with our neighbors and with our local communities that our ancestors were forced into by circumstance, we feel ourselves to be more and more independent of one another. As we become more and more dependent on others, we become less and less conscious of our dependence on others. This is the paradox of trade in the modern world.` },
    { id: 'cet6-2024-12-s3-mp-H', marker: 'H', text: `The false consciousness that this paradox generates causes havoc on the debates we have about free trade. There is scarcely a single commodity in any American household that isn't dependent for its manufacture and sale, through one supply chain or another, on scores of different people spread out across the entire globe. But as Tocqueville already foresaw in 1840, we do not feel dependent on these strangers for our way of life. No sense of the dependence of our own material welfare on their work ever strikes our national consciousness. We rarely contemplate the globalized avenues of free trade with gratitude.` },
    { id: 'cet6-2024-12-s3-mp-I', marker: 'I', text: `There are two reasons for this. The first, to put it bluntly, is money. Money allows us to purchase the work of others without giving any thought to them as human beings. Unlike our ancestors in their primitive townships, we rarely have to meet face-to-face the people who've invented, built, shipped, or supplied our goods. No relationship has to be built before an exchange can take place. Simply agree on a price, and you can have any goods you wish without taking a second thought for the human being involved on the other side of the transaction. In this way, money makes us feel more independent than we actually are. Each of us senses the hold that it has over our fellows. We know that if we bid highly enough we can buy ourselves out of the time-consuming labor of building relationships. Money is kind of like magic in that way. It gives us a set of rituals to perform and promises that if we do so we'll be able to wield power over others. The illusion is created that having enough money to buy something is the equivalent of knowing how to make it yourself. Gratitude for the anonymous men and women who make up the supply chain rarely makes its way into our consciousness.` },
    { id: 'cet6-2024-12-s3-mp-J', marker: 'J', text: `Anonymity, in fact, is the second root cause of the free-trade paradox. Modernity has emancipated everyone from the limits of location and community. By and large, when we trade, we trade with strangers; when we vote, we vote for strangers; when we watch, read, or listen to stories, the tellers of the tales are strangers. As opposed to the ancestors Tocqueville compares us to, we do not know the people with whom we have to do, in either the economic or the political sphere. This is simply the shadow side of the miracle of markets, which, for the first time in history, have allowed strangers to look after each other. They've also allowed each of us to live more and more of our lives exclusively as strangers to other people. This is how Tocqueville—rather pessimistically—describes us: Each, standing apart, is like a stranger to the destiny of others; his children and personal friends forming for him the entire human race. As for the remainder of his fellow citizens, he is beside them, but he does not see them. He touches them, but he does not feel them. He exists only in and for himself.` },
    { id: 'cet6-2024-12-s3-mp-K', marker: 'K', text: `The last sentence but one is as apt a summary as one could hope to come by of how each of us functions in the modern economy: "He touches them, but he does not feel them."` },
    { id: 'cet6-2024-12-s3-mp-L', marker: 'L', text: `This is the greatest challenge facing defenders of free trade. It's exceedingly difficult for human beings to feel gratitude toward strangers, and the global marketplace that has made us so rich has also made us strangers to one another. Our brains are hardwired for tribal life, and tribes do not take kindly to strangers. Impressing a sense of dependence upon and gratitude toward foreign strangers is therefore an uphill task.` },
    { id: 'cet6-2024-12-s3-mp-M', marker: 'M', text: `If free-traders are going to win policy arguments in the future, they'll have to find a way of forging bonds of affection between American consumers and foreign producers. Only by de-anonymizing the men and women who supply us with the goods and services we enjoy from overseas and by creating a sense of solidarity and relationship across borders that transcends economic interest can free trade win the day. Otherwise, the inborn biological upper hand that protectionists have in the form of nationalist solidarity is bound to win the day at the ballot box.` },
  ],
};

